import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import Navbar from './components/Navbar';
import UserLogin from './pages/user/UserLogin';
import UserRegister from './pages/user/UserRegister';
import UserDashboard from './pages/user/UserDashboard';
import AdminCheckout from './pages/admin/AdminCheckout';
import AdminCardRegister from './pages/admin/AdminCardRegister';
// Note: You will need to create AdminLogin.jsx using the same pattern as UserLogin
import AdminLogin from './pages/admin/AdminLogin'; 
import ProtectedRoute from './components/ProtectedRoute'; // For Users
import AdminRoute from './components/AdminRoute'; // Create this to check for 'adminInfo'

function App() {
  console.log("Checking Imports:", { UserLogin, UserRegister, UserDashboard, AdminCheckout, AdminCardRegister, AdminLogin, ProtectedRoute, AdminRoute, Navbar });
  return (
    <BrowserRouter>
      {/* Global Navbar */}
      <Navbar />

      {/* Toast Notifications */}
      <Toaster position="top-right" toastOptions={{ duration: 3000 }} />

      <main className="min-h-screen bg-gray-50 py-8 px-4 sm:px-6">
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<UserLogin />} />
          <Route path="/user/login" element={<UserLogin />} />
          <Route path="/user/register" element={<UserRegister />} />
          <Route path="/admin/login" element={<AdminLogin />} />

          {/* Protected Student Routes */}
          <Route path="/user/dashboard" element={
            <ProtectedRoute>
              <UserDashboard />
            </ProtectedRoute>
          } />

          {/* Protected Admin Routes */}
          <Route path="/admin/checkout" element={
            <AdminRoute>
              <AdminCheckout />
            </AdminRoute>
          } />
          <Route path="/admin/register" element={
            <AdminRoute>
              <AdminCardRegister />
            </AdminRoute>
          } />
        </Routes>
      </main>
    </BrowserRouter>
  );
}

export default App;
